  *, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }

  :root {
    --espresso: #1A1410;
    --amber: #C47E3B;
    --filter: #F5F0E8;
    --steel: #8A9398;
    --stone: #4A4543;
