    overflow-x: hidden;
  }

  /* ---------- HERO ---------- */
  .hero {
    position: relative;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: var(--filter);
  }

  .hero-ripples {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
  }

  .ripple {
    position: absolute;
    border: 1px solid rgba(196, 126, 59, 0.25);
    border-radius: 50%;
    animation: bloom 6s ease-out infinite;
    opacity: 0;
  }
  .ripple:nth-child(1) { width: 80px; height: 80px; animation-delay: 0s; }
  .ripple:nth-child(2) { width: 80px; height: 80px; animation-delay: 1.2s; }
  .ripple:nth-child(3) { width: 80px; height: 80px; animation-delay: 2.4s; }
  .ripple:nth-child(4) { width: 80px; height: 80px; animation-delay: 3.6s; }
  .ripple:nth-child(5) { width: 80px; height: 80px; animation-delay: 4.8s; }

  @keyframes bloom {
