  /* ---------- BREW TIMELINE ---------- */
  .timeline {
    max-width: 960px;
    margin: 0 auto;
    padding: 6rem 2rem;
  }

  .brew-stage {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 3rem;
